public void sortColors(int[] nums) {
        int start = 0, end = nums.length - 1;
        int mid = start;
        while (mid <= end) {
            if (nums[mid] == 0) {
                int temp = nums[start];
                nums[start] = nums[mid];
                nums[mid] = temp;
                start++;
                mid = start;
            } else if (nums[mid] == 2) {
                int temp = nums[end];
                nums[end] = nums[mid];
                nums[mid] = temp;
                end--;
            } else {
                mid++;
            }
        }
    }

public void sortColors(int[] nums) {
    int lt = 0, i = 0, gt = nums.length - 1;
    while (i <= gt) {
        if (nums[i] == 2) {
            swap(nums, i, gt);
            gt--;
        } else if (nums[i] == 0) {
            swap(nums, i, lt);
            lt++;
            i++;
        } else {
            i++;
        }
    }
}

private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

