public void sortColors(int[] nums) {
        // 分区不变量：
        //   [0,lt)   全 0
        //   [lt,i)   全 1
        //   (gt,n-1] 全 2
        //   [i,gt]   未处理 → 循环条件 i<=gt（i==gt 时那一格仍未处理）
        int lt = 0, i = 0, gt = nums.length - 1;
        while (i <= gt) {
            if (nums[i] == 2) {
                swap(nums, i, gt);
                gt--;
            } else if (nums[i] == 0) {
                swap(nums, lt, i);
                lt++;
                i++;
            } else {
                i++;
            }
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
